// orch-no-blind-sleep — OpenCode plugin wrapper for hooks/no_blind_sleep.py
//
// Generated by `orch hooks install --agent opencode` (lib/orchlib/hooks.py)
// from hooks/opencode/orch-no-blind-sleep.js. Do not edit the installed copy:
// re-run the installer instead.
//
// Why a wrapper: OpenCode has no shell-command hooks, only JS plugins. The
// policy itself stays in the single Python hook so devin/claude/codex/opencode
// never drift apart. Shape follows the plugin API used by Orca's own
// orca-opencode-status.js: `export const X = async (ctx) => ({ hooks })`.
//
// Contract: on `tool.execute.before` for the bash tool, send
// {"tool": "bash", "args": {...}} to the Python hook on stdin. Exit 2 = block
// -> throw Error(reason) (OpenCode surfaces the message to the model and
// skips the tool). Any other outcome, including the hook failing to run,
// allows the call: a hook bug must never wedge an unattended worker.
import { spawnSync } from "child_process";

const PYTHON = __ORCH_PYTHON__;
const HOOK = __ORCH_HOOK_SCRIPT__;
const SHELL_TOOLS = new Set(["bash", "shell", "exec"]);

export const OrchNoBlindSleepPlugin = async (_ctx) => ({
  "tool.execute.before": async (input, output) => {
    const tool = String((input && input.tool) || "").toLowerCase();
    if (!SHELL_TOOLS.has(tool)) return;
    const args = (output && output.args) || {};
    let res;
    try {
      res = spawnSync(PYTHON, [HOOK, "--agent", "opencode"], {
        input: JSON.stringify({ tool, args }),
        encoding: "utf8",
        timeout: 5000,
      });
    } catch (_e) {
      return;
    }
    if (!res || res.status !== 2) return;
    let reason = (res.stderr || "").trim();
    try {
      const parsed = JSON.parse(res.stdout || "{}");
      if (parsed && parsed.reason) reason = parsed.reason;
    } catch (_e) {
      // stderr already carries the reason
    }
    throw new Error(reason || "Blocked by orch no_blind_sleep hook");
  },
});

export default OrchNoBlindSleepPlugin;
